INSERT INTO articles(name, id_module, id_quiz, content) VALUES
    ('Основы финансовой грамотности', 1, NULL, '{"data": [{"type": "header", "text": "Основы финансовой грамотности: Зачем вообще инвестировать?"}, {"type": "paragraph", "text": "Многие люди традиционно считают, что для обеспечения безбедного будущего вполне достаточно просто откладывать часть зарплаты под матрас или, в лучшем случае, на обычный сберегательный счет до востребования. В обществе десятилетиями культивировалась идея накопительства в его самом примитивном виде."}, {"type": "paragraph", "text": "Однако в современном, динамично меняющемся мире деньги имеют неприятное свойство постоянно терять свою покупательную способность с течением времени. Инвестирование — это не просто какой-то абстрактный способ разбогатеть для избранных, это абсолютно необходимый инструмент для защиты вашего личного капитала от неизбежного обесценивания."}, {"type": "header", "text": "Иллюзия стабильности наличных денег"}, {"type": "paragraph", "text": "Кажется, что пачка купюр в сейфе — это гарант надежности. Она не зависит от биржевых котировок, банкротств корпораций или геополитических кризисов. Но эта стабильность иллюзорна. Каждый день невидимый налог съедает часть этих средств, делая вас беднее, даже если номинальное количество купюр остается прежним."}, {"type": "paragraph", "text": "Чтобы это понять, достаточно вспомнить, что можно было купить на тысячу рублей десять лет назад и что можно купить сегодня. Именно поэтому хранение крупных сумм в наличных — это, парадоксально, самый гарантированный способ медленно, но верно терять свои сбережения."}, {"type": "header", "text": "Как заставить деньги работать?"}, {"type": "paragraph", "text": "Ключевое отличие инвестирования от простого, пассивного накопления заключается в том, что ваши деньги начинают работать на вас, выступая в роли неутомимых сотрудников. Вместо того чтобы лежать мертвым грузом, капитал направляется в различные финансовые инструменты, которые генерируют дополнительную стоимость круглосуточно."}, {"type": "paragraph", "text": "Это могут быть акции развивающихся компаний, долговые обязательства (облигации) надежных эмитентов или даже классические депозиты. Смысл в том, чтобы передать капитал тем, кто в нем нуждается для создания реальной экономической ценности, получив взамен свою долю прибыли."}, {"type": "warning", "text": "Важное правило: инвестиции всегда сопряжены с определенным уровнем риска. Никогда не инвестируйте последние деньги или средства, которые могут понадобиться вам в ближайшие месяцы на непредвиденные расходы. Фундамент любого инвестирования — это сформированная финансовая подушка безопасности на 3-6 месяцев жизни."}, {"type": "header", "text": "Психологический барьер и первые шаги"}, {"type": "paragraph", "text": "Самая большая сложность для новичка — это преодолеть страх потери и сделать первый шаг. Финансовые рынки кажутся сложной системой с графиками, терминами и постоянными рисками обвала."}, {"type": "paragraph", "text": "Начните с малого. Определите свою глобальную цель, сроки инвестирования и терпимость к риску. Не пытайтесь сразу угадать, какие акции взлетят завтра, лучше сфокусируйтесь на изучении базовых понятий, таких как доходность, инфляция и сложный процент, которые станут вашим компасом в мире финансов."}]}'),
    ('Простой процент: Базовая механика', 1, 1, '{"data": [{"type": "header", "text": "Простой процент: Базовая механика доходности"}, {"type": "paragraph", "text": "Чтобы уверенно двигаться в мире финансов, необходимо досконально понимать механизмы формирования прибыли. Простой процент — это самый понятный, исторически древний и прямолинейный метод начисления дохода на вложенный капитал. Он является отправной точкой для любых финансовых расчетов."}, {"type": "paragraph", "text": "При использовании простого процента доход начисляется исключительно на первоначальную сумму ваших инвестиций. Заработанные сверху проценты не плюсуются к основной сумме для дальнейших расчетов, а как бы откладываются в отдельную стопку, не участвуя в дальнейшей генерации прибыли."}, {"type": "header", "text": "Наглядный пример расчетов"}, {"type": "paragraph", "text": "Давайте рассмотрим классический, максимально упрощенный пример. Допустим, вы вложили 100 000 рублей под фиксированные 10% годовых на срок в 3 года. По формуле простого процента каждый год вы будете получать ровно 10 000 рублей дохода, ни рублем больше или меньше."}, {"type": "paragraph", "text": "Динамика вашего капитала будет выглядеть так: к концу первого года у вас будет 110 000, в конце второго — 120 000, а в конце третьего — 130 000 рублей. Рост идет ровно на 10 тысяч ежегодно. Это линейная, абсолютно предсказуемая математическая прогрессия."}, {"type": "warning", "text": "Главный минус простого процента — колоссальная упущенная выгода. Ваш заработанный доход просто лежит рядом с основным капиталом и не приносит новых денег. Со временем макроэкономические факторы начнут неумолимо съедать реальную ценность этих неработающих процентов."}, {"type": "header", "text": "Где применяется линейный рост?"}, {"type": "paragraph", "text": "Несмотря на очевидные недостатки на длинной дистанции, простой процент активно используется в современной финансовой системе. В чистом виде он часто встречается в краткосрочных займах между физическими лицами или компаниями."}, {"type": "paragraph", "text": "Также по этому принципу работают некоторые виды купонных облигаций, где выплаты (купоны) инвестор сразу выводит на отдельный счет и тратит на текущие нужды, а также классические банковские вклады без функции автоматического реинвестирования."}, {"type": "header", "text": "Ограничения метода"}, {"type": "paragraph", "text": "Математически формула простого процента выглядит элементарно: Итоговая сумма = Начальная сумма * (1 + Ставка * Время). График такого роста представляет собой прямую линию, идущую вверх с одинаковым углом наклона."}, {"type": "paragraph", "text": "Это стабильно, надежно, легко рассчитывается в уме, но, к сожалению, совершенно не позволяет капиталу расти взрывными темпами на длинных горизонтах. Именно поэтому профессиональные инвесторы всегда стремятся перейти к более продвинутым методам реинвестирования."}]}'),
    ('Сложный процент: Восьмое чудо света', 1, 2, '{"data": [{"type": "header", "text": "Сложный процент: Восьмое чудо света"}, {"type": "paragraph", "text": "Если простой процент — это линейное движение пешком, то сложный процент — это полет на ракете, которая постоянно ускоряется. Знаменитый физик Альберт Эйнштейн не зря называл сложный процент восьмым чудом света, добавляя известную фразу: «Тот, кто понимает его, зарабатывает его – тот, кто не понимает, платит его»."}, {"type": "paragraph", "text": "Сложный процент — это фундаментальная концепция «процента на процент». При этом подходе вся заработанная за период прибыль прибавляется к основной сумме, и в следующем периоде доход начисляется уже на эту увеличенную, растолстевшую базу. Капитал начинает расти как снежный ком, катящийся с горы."}, {"type": "header", "text": "Механика капитализации в действии"}, {"type": "paragraph", "text": "Этот волшебный процесс в финансах официально называется капитализацией. Возьмем наши базовые 100 000 рублей под те же 10% годовых. В первый год вы получаете 10 000 рублей прибыли, и на счету становится 110 000. Пока разницы с простым процентом нет."}, {"type": "paragraph", "text": "Но во второй год 10% будут начисляться уже на всю сумму (110 000 рублей), принеся вам не 10, а 11 000 рублей. В третий год базой станет 121 000 рублей, а прибыль составит 12 100 рублей. Ваша прибыль начинает генерировать свою собственную, новую прибыль."}, {"type": "warning", "text": "Вся магия сложного процента раскрывается исключительно на длительных сроках. В первые 3-5 лет разница с простым процентом кажется незначительной и не вызывает восторга. Но спустя 10, 20 или 30 лет график доходности превращается в крутую экспоненциальную кривую, уходящую в небеса."}, {"type": "header", "text": "Фактор времени и частота начислений"}, {"type": "paragraph", "text": "В формуле сложного процента время имеет гораздо больший вес, чем размер ставки или начальная сумма. Именно поэтому человек, начавший инвестировать скромные суммы в 20 лет, к пенсии легко обгонит того, кто начал вкладывать огромные деньги в 45 лет."}, {"type": "paragraph", "text": "Также огромную роль играет частота начисления и реинвестирования процентов. Чем чаще это происходит, тем быстрее растет капитал. Ежемесячная капитализация даст вам математически больший итоговый результат за год, чем одна выплата в конце года при той же самой годовой процентной ставке."}, {"type": "header", "text": "Регулярные пополнения как катализатор"}, {"type": "paragraph", "text": "Сам по себе сложный процент прекрасен, но его истинная мощь раскрывается при комбинировании с дисциплиной. Если к сложному проценту добавить регулярные ежемесячные доносы (например, откладывать строго по 10% от зарплаты каждый месяц), результат превзойдет все ожидания."}, {"type": "paragraph", "text": "Эти регулярные финансовые инъекции постоянно, месяц за месяцем, увеличивают базу, на которую ложится сложный процент. Они работают как ракетное топливо для вашего инвестиционного портфеля, многократно сокращая время пути к заветной финансовой независимости."}]}'),
    ('Инфляция и Налоги', 2, NULL, '{"data": [{"type": "header", "text": "Скрытые враги капитала: Инфляция и Налоги"}, {"type": "paragraph", "text": "В мире финансов цифры на экране часто бывают обманчивы. Когда мы смотрим на доходность депозита в 12% или 15% годовых, нам кажется, что наши деньги стремительно растут, а благосостояние улучшается. Мы радуемся номинальным значениям, забывая о фундаментальных экономических процессах."}, {"type": "paragraph", "text": "Однако настоящий, грамотный инвестор всегда должен считать только реальную доходность. Это та доходность, которая остается после того, как вы очистите свои доходы от влияния двух главных, безжалостных врагов любого капитала: макроэкономической инфляции и государственных налогов."}, {"type": "header", "text": "Инфляция — невидимый пожиратель денег"}, {"type": "paragraph", "text": "Инфляция — это непрерывный процесс обесценивания денег, при котором цены на базовые товары и услуги растут год от года. Она работает как медленный яд для ваших сбережений. Если ваша инвестиция принесла 10% за год, а официальная инфляция составила 8%, ваша реальная покупательная способность выросла всего на жалкие 2%."}, {"type": "paragraph", "text": "Если же инфляция оказывается выше вашей доходности (например, инфляция 12%, а вклад дает 8%), вы фактически теряете деньги. Парадокс в том, что цифры на вашем банковском счету увеличиваются, но купить на них вы можете меньше, чем год назад."}, {"type": "warning", "text": "Держите в уме железобетонное правило: наличные деньги, бережно хранящиеся дома под матрасом, гарантированно теряют свою стоимость каждый день со скоростью инфляции. Минимальная задача абсолютно любых инвестиций — хотя бы покрыть процент инфляции."}, {"type": "header", "text": "Налогообложение: плата за успех"}, {"type": "paragraph", "text": "Второй, не менее важный фактор — налоги. Любая прибыль, полученная вами на фондовой бирже, при продаже недвижимости или на банковском вкладе, по закону подлежит налогообложению. Государство всегда заберет свой процент от вашего успеха (обычно это 13% или 15% НДФЛ в зависимости от суммы)."}, {"type": "paragraph", "text": "При долгосрочном инвестировании с использованием магии сложного процента критически важно понимать, как и когда списывается этот налог. Если налог удерживается ежегодно или ежемесячно, математическая база для вашего сложного процента будет расти значительно медленнее, так как часть прибыли постоянно изымается из оборота."}, {"type": "header", "text": "Оптимизация и законные льготы"}, {"type": "paragraph", "text": "К счастью, существуют инструменты для защиты. Многие продвинутые инвесторы выбирают биржевые фонды, которые реинвестируют дивиденды внутри себя, позволяя не платить налог с каждой выплаты вплоть до момента окончательной продажи актива через много лет."}, {"type": "paragraph", "text": "Кроме того, государство само предлагает различные льготы для стимулирования инвестиций, такие как Индивидуальные инвестиционные счета (ИИС). Они позволяют совершенно законно не платить налог с полученной прибыли или даже ежегодно возвращать часть ранее уплаченных государству налогов с вашей зарплаты."}]}'),
    ('Риск и Доходность', 2, 3, '{"data": [{"type": "header", "text": "Риск и Доходность: Выбор метода инвестирования"}, {"type": "paragraph", "text": "В мире финансов существует одно железное, нерушимое правило, которое действует всегда и везде, независимо от экономической ситуации: риск и доходность навсегда связаны прочной нитью. Они идут рука об руку, как две стороны одной медали, и разделить их невозможно."}, {"type": "paragraph", "text": "Абсолютно невозможно получить сверхвысокую гарантированную доходность без соизмеримого риска потерять значительную часть или даже весь свой первоначальный капитал. В зависимости от личной терпимости к просадкам, жизненной ситуации и поставленных целей, инвесторы выбирают совершенно разные стратегии работы на рынке."}, {"type": "header", "text": "Надежный метод: сохраняем заработанное"}, {"type": "paragraph", "text": "Надежный (или консервативный) метод инвестирования ставит защиту уже имеющегося капитала превыше всего. Главная цель здесь — не приумножить капитал в разы, а просто спасти его от инфляционного обесценивания, сохранив покупательную способность."}, {"type": "paragraph", "text": "Здесь используются исключительно инструменты с фиксированной, заранее известной доходностью: государственные облигации (ОФЗ), крупные корпоративные облигации топовых компаний и классические банковские вклады. Доходность таких инструментов обычно лишь слегка обгоняет инфляцию. Вы не станете сказочно богатым, но и не потеряете свои деньги в кризис."}, {"type": "warning", "text": "Если кто-то в интернете, в рекламе или по телефону обещает вам доходность в 30-50% годовых и при этом уверяет, что это «абсолютно безрисково и гарантировано», можете быть уверены на 100% — перед вами мошенники. Гарантировать можно только минимальную доходность."}, {"type": "header", "text": "Умеренный подход: в поисках баланса"}, {"type": "paragraph", "text": "Умеренный подход подразумевает поиск разумного баланса между защитой и ростом. В таком портфеле часть средств лежит в надежных облигациях, выполняя роль якоря и подушки безопасности, а часть направляется в акции крупных, стабильных компаний с выплатой дивидендов."}, {"type": "paragraph", "text": "Этот метод позволяет стабильно обгонять инфляцию и наращивать капитал быстрее, но требует от инвестора психологической готовности видеть временные небольшие минусы на своем брокерском счете во время сезонных коррекций или макроэкономических кризисов."}, {"type": "header", "text": "Рискованный метод: пан или пропал"}, {"type": "paragraph", "text": "Рискованный (агрессивный) метод подходит только для людей с крепкими нервами и длинным горизонтом инвестирования. Он предполагает покупку акций молодых стартапов, венчурные инвестиции, работу с криптовалютами и частое использование заемных средств брокера (маржинальная торговля)."}, {"type": "paragraph", "text": "Доходность в таких инструментах может составлять сотни и тысячи процентов за короткий срок. Однако платой за такую возможность является колоссальный риск полной потери депозита. Этот метод категорически противопоказан новичкам и тем, кто инвестирует последние сбережения."}]}'),
    ('Систематичность: Секрет успеха', 3, NULL, '{"data": [{"type": "header", "text": "Систематичность: Главный секрет успеха"}, {"type": "paragraph", "text": "Среди новичков и людей, далеких от финансового мира, прочно укоренился один вредный миф: для того чтобы успешно стартовать на бирже и стать настоящим инвестором, нужен огромный, многомиллионный первоначальный капитал. Многим кажется, что с тысячей рублей там делать нечего."}, {"type": "paragraph", "text": "Однако многолетняя мировая практика и суровая статистика показывают совершенно иное. Железная дисциплина и математическая систематичность на длинной дистанции всегда бьют разовые крупные вложения. Метод регулярных, методичных инвестиций — это и есть настоящая основа спокойного накопления капитала."}, {"type": "header", "text": "Магия усреднения стоимости"}, {"type": "paragraph", "text": "Одной из самых эффективных и психологически комфортных стратегий для частного инвестора является стратегия усреднения долларовой стоимости (Dollar Cost Averaging). Ее суть до гениального проста и не требует глубоких познаний в фундаментальном анализе бизнеса."}, {"type": "paragraph", "text": "Она заключается в том, что вы покупаете выбранные активы на фиксированную сумму с равными временными интервалами (например, строго каждое 5 число месяца на 10 000 рублей). При этом вы полностью игнорируете новостной фон, прогнозы аналитиков и то, что прямо сейчас происходит на графиках."}, {"type": "warning", "text": "Любая попытка угадать идеальный момент для покупки актива (так называемый маркет-тайминг) приводит к потере денег в 90% случаев. Вы всегда будете либо слишком долго ждать идеального дна, упуская весь рост, либо покупать на самом пике из-за страха упустить выгоду (синдром FOMO)."}, {"type": "header", "text": "Как стратегия работает в кризис?"}, {"type": "paragraph", "text": "Допустим, в мире случился экономический шок, и фондовый рынок начал стремительно падать. Большинство непрофессионалов впадает в панику, продает активы в минус и навсегда уходит с биржи. Но для системного инвестора падение рынка — это долгожданная глобальная распродажа!"}, {"type": "paragraph", "text": "На свои привычные ежемесячные 10 000 рублей вы сможете купить гораздо больше подешевевших, но качественных активов. На высоких фазах рынка вы покупаете меньше штук за те же деньги, на низких — больше. В итоге, когда рынок неизбежно пойдет вверх, эти активы принесут огромную прибыль, а средняя цена покупки окажется очень выгодной."}, {"type": "header", "text": "Эмоции и автоматизация"}, {"type": "paragraph", "text": "Главный секрет применения этой стратегии заключается в полной изоляции собственных эмоций. Лучший способ следовать этому плану — настроить автоматическое пополнение брокерского счета прямо в день получения зарплаты, чтобы деньги уходили в работу до того, как вы решите их потратить на пассивы."}, {"type": "paragraph", "text": "К процессу инвестирования нужно относиться предельно обыденно. Относитесь к нему как к оплате счетов за коммунальные услуги или интернет. Это просто обязательный, неотменяемый ежемесячный платеж самому себе, в свое безопасное финансовое будущее."}]}'),
    ('Анатомия фондового рынка', 3, 4, '{"data": [{"type": "header", "text": "Анатомия фондового рынка"}, {"type": "paragraph", "text": "Для неподготовленного человека фондовый рынок выглядит как хаотичное скопление непонятных аббревиатур, мелькающих зеленых и красных цифр, и непонятных графиков на экранах трейдеров. Это кажется невероятно сложным и запутанным механизмом, доступным только математическим гениям."}, {"type": "paragraph", "text": "Однако, если отбросить весь информационный шум, базово фондовый рынок состоит всего из двух основных типов финансовых инструментов: долевых и долговых. Глубокое понимание разницы между ними и их механики — это абсолютный фундамент успешного составления любого инвестиционного портфеля."}, {"type": "header", "text": "Акции: статус совладельца бизнеса"}, {"type": "paragraph", "text": "Долевые инструменты, более известные всем как акции, — это ваш пропуск в реальный бизнес. Покупая даже одну акцию Газпрома, Сбербанка или Apple, вы юридически покупаете микро-кусочек этого огромного бизнеса. С этого момента вы становитесь полноправным совладельцем компании."}, {"type": "paragraph", "text": "Суть заработка здесь двояка. Если компания развивается, захватывает рынки и зарабатывает больше денег, её внутренняя ценность растет, а значит, увеличивается и цена вашей акции на бирже. Кроме того, успешная компания регулярно делится с акционерами частью своей чистой прибыли в виде прямых денежных выплат — дивидендов."}, {"type": "warning", "text": "Помните, что акции — это невероятно волатильный актив. Их цена меняется каждую секунду, реагируя на политические новости, квартальные отчеты и даже посты блогеров в социальных сетях. Если компания обанкротится, цена ее акций упадет до нуля. Это инструмент, требующий стальных нервов и времени."}, {"type": "header", "text": "Облигации: деньги в долг"}, {"type": "paragraph", "text": "Второй столп рынка — долговые инструменты, или облигации. Механика здесь совершенно иная. Покупая облигацию, вы не становитесь владельцем бизнеса. Вы просто даете свои деньги в долг — государству, муниципалитету или крупной корпорации — под заранее оговоренный, фиксированный процент."}, {"type": "paragraph", "text": "Вы заранее знаете абсолютно все вводные: в какую дату вам вернут основную сумму долга (номинал) и в какие числа месяца вам будут выплачивать проценты (купоны) за пользование вашими деньгами. Облигации служат амортизатором в портфеле инвестора, защищая его в моменты, когда акции летят в пропасть."}, {"type": "header", "text": "Фонды: решение для ленивых"}, {"type": "paragraph", "text": "Для подавляющего большинства людей, у которых есть основная работа, хобби и семья, самостоятельный выбор и анализ десятков акций — непозволительная роскошь. Для них индустрия придумала биржевые инвестиционные фонды (ETF и ПИФы)."}, {"type": "paragraph", "text": "Покупая всего один пай такого фонда, вы покупаете сразу готовую, сбалансированную «корзину», внутри которой лежат сотни ценных бумаг различных компаний, тщательно отобранных профессиональными управляющими. Это самый простой и дешевый способ купить весь рынок целиком всего одним кликом."}]}'),
    ('Диверсификация и психология', 3, 5, '{"data": [{"type": "header", "text": "Диверсификация и психология рынка"}, {"type": "paragraph", "text": "Знаменитая поговорка «Не кладите все яйца в одну корзину» — это не просто житейская народная мудрость, подходящая для похода на рынок. В контексте фондовой биржи это строгое, математически и статистически обоснованное правило управления рисками, игнорирование которого ведет к катастрофе."}, {"type": "paragraph", "text": "На финансовом языке этот процесс называется диверсификацией. Она означает грамотное распределение вашего капитала по совершенно разным классам активов, различным секторам экономики, валютам и даже географическим юрисдикциям. Цель — сделать так, чтобы падение одного элемента не уничтожило весь ваш портфель."}, {"type": "header", "text": "Как работает правильная защита?"}, {"type": "paragraph", "text": "Представьте, что вы вложили все свои сбережения исключительно в акции одной, казалось бы, надежной IT-компании. Если у неё случится масштабная утечка данных клиентов или сменится руководство, акции могут рухнуть на 50% за день. Ваш капитал ополовинится из-за одной новости."}, {"type": "paragraph", "text": "Но если в вашем портфеле IT-сектор занимает лишь 10%, а остальное распределено между медициной, добычей нефти, продуктовым ритейлом, золотом и государственными облигациями, то падение акций IT-компании пройдет для вас почти незаметно. Убыток будет компенсирован ростом других, не связанных секторов экономики."}, {"type": "warning", "text": "Опасайтесь ложной диверсификации. Покупка десяти разных акций банков — это не диверсификация. В случае масштабного банковского кризиса они упадут все вместе, синхронно. Правильная диверсификация — это покупка активов, которые ведут себя по-разному в одних и тех же экономических условиях (например, акции падают, а золото растет)."}, {"type": "header", "text": "Битва с собственным мозгом"}, {"type": "paragraph", "text": "Как показывает практика, самый главный и коварный враг инвестора — это он сам. Наша психика, сформированная тысячелетиями эволюции, совершенно не приспособлена к адекватной работе на финансовых рынках. Она выдает неправильные реакции на графики и цифры."}, {"type": "paragraph", "text": "Когда все кругом падает и СМИ предрекают конец света, древние инстинкты кричат: «Беги! Продавай всё, спасай хотя бы остатки!». А когда на рынке эйфория и какая-то сомнительная акция выросла на 300%, мозг требует: «Покупай на все деньги, бери кредиты, или упустишь шанс стать миллионером!»."}, {"type": "header", "text": "Дисциплина важнее интеллекта"}, {"type": "paragraph", "text": "Именно эти два первобытных чувства — паника и жадность — разрушили больше инвестиционных счетов, чем любой, самый тяжелый экономический кризис в истории человечества. Биржа устроена таким образом, что она методично перекачивает деньги от нетерпеливых и эмоциональных людей к терпеливым и расчетливым."}, {"type": "paragraph", "text": "Чтобы спокойно спать по ночам, запишите свою личную стратегию на листке бумаги еще до покупки первой акции. Пообещайте себе не заглядывать в терминал брокера каждый день. Опирайтесь исключительно на математические законы и долгосрочную статистику рынка, а не на эмоции толпы."}]}');
